import sys

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    index = 0
    t = int(data[index])
    index += 1

    results = []

    for _ in range(t):
        n = int(data[index])
        m = int(data[index + 1])
        index += 2

        grid = []
        for _ in range(n):
            row = list(map(int, data[index:index + m]))
            index += m
            grid.append(row)

        def is_good_grid(grid):
            for row in grid:
                for j in range(1, m):
                    if row[j] < row[j - 1]:
                        return False
            return True

        if is_good_grid(grid):
            results.append("1 1")
            continue

        found = False
        for i in range(m):
            for j in range(i, m):
                new_grid = [row[:] for row in grid]
                for k in range(n):
                    new_grid[k][i], new_grid[k][j] = new_grid[k][j], new_grid[k][i]

                if is_good_grid(new_grid):
                    results.append(f"{i + 1} {j + 1}")
                    found = True
                    break
            if found:
                break

        if not found:
            results.append("-1")

    print("\n".join(results))

if __name__ == "__main__":
